"""Self-contained local UI: no CDN, analytics, fonts or external network requests."""
HTML = r'''<!doctype html><html lang="tr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>IPScans · LPR Pro Local</title><style>
:root{font:15px 'Segoe UI',sans-serif;color:#10131a;background:#f7f8fa}*{box-sizing:border-box}body{margin:0}header{padding:24px 5%;background:white;border-bottom:1px solid #e5e7eb;display:flex;align-items:center;gap:20px}header strong{font-size:23px;letter-spacing:-1px}header span{color:#647084}header button{margin-left:auto}main{max-width:1380px;margin:36px auto;padding:0 28px}h1{font-size:38px;letter-spacing:-1.5px;margin:8px 0}h2{font-size:20px}p{line-height:1.6;color:#647084}.eyebrow{color:#2f6bff;font-weight:700;font-size:12px;letter-spacing:2px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:18px;padding:24px;margin:18px 0}.grid{display:grid;grid-template-columns:2fr 1fr;gap:22px}.metrics{display:flex;gap:18px;flex-wrap:wrap}.metric{flex:1;min-width:150px}.metric b{display:block;font-size:30px;margin:10px 0}.metric span{color:#647084}input,select,button{font:inherit;border:1px solid #dce1e8;border-radius:9px;padding:11px 14px;background:#fff;color:#10131a}button{cursor:pointer}button:hover{border-color:#2f6bff}button.primary{background:#10131a;color:white;border-color:#10131a}button:disabled{opacity:.45;cursor:default}label{display:block;margin:14px 0 6px;color:#464a53}input:not([type=checkbox]),select{width:100%}table{width:100%;border-collapse:collapse;font-size:13px}td,th{padding:14px 10px;border-bottom:1px solid #edf0f3;text-align:left}th{color:#647084;font-weight:500}tr[data-id]{cursor:pointer}tr[data-id]:hover{background:#eef3ff}.scroll{overflow:auto}.badge{border-radius:20px;padding:5px 9px;background:#e9f0ff;color:#245bd6;font-size:12px}.actions{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}#notice{white-space:pre-wrap;color:#245bd6;min-height:24px}#login{max-width:430px;margin:70px auto}#details img{max-width:100%;max-height:230px;border-radius:10px}#result{background:#f7f8fa;border-radius:10px;padding:15px;white-space:pre-wrap}small{color:#647084}dialog{max-width:760px;width:90%;border:1px solid #e5e7eb;border-radius:18px;padding:28px}dialog::backdrop{background:#10131a88}[hidden]{display:none!important}@media(max-width:900px){.grid{grid-template-columns:1fr}header span{display:none}h1{font-size:30px}}
</style><header><strong>ipscans<span style="color:#2f6bff">.</span></strong><span>LPR PRO / YEREL KONTROL</span><button id="logout" hidden>Oturumu kapat</button></header>
<main><section id="login" class="card"><div class="eyebrow">BU BİLGİSAYARDA · YEREL</div><h1>Kontrol sizde.</h1><p>Masaüstünde oluşturduğunuz LPR Pro hesabıyla giriş yapın.</p><form id="signIn"><label for="username">Kullanıcı adı</label><input id="username" autocomplete="username" required maxlength="64"><label for="password">Parola</label><input id="password" type="password" autocomplete="current-password" required maxlength="256"><div class="actions"><button class="primary">Güvenli giriş</button></div></form></section>
<div id="notice" role="status" aria-live="polite"></div><section id="workspace" hidden><div class="eyebrow">LPR PRO · MASAÜSTÜ + LOCAL</div><h1>Her geçiş, net bir kayıt.</h1><p id="identity"></p><div class="metrics"><div class="card metric"><span>Kayıtlı kameralar</span><b id="cameraCount">0</b></div><div class="card metric"><span>Son olaylar</span><b id="eventCount">0</b></div><div class="card metric"><span>İnceleme bekleyen · son 100</span><b id="reviewCount">0</b></div></div>
<div class="grid"><section><div class="card"><h2>Geçiş akışı</h2><p>Son 100 kayıt · Detay, görsel kanıt ve AI incelemesi için bir satır seçin.</p><input id="search" type="search" placeholder="Plaka veya kamera ara" aria-label="Olaylarda ara"><div class="scroll"><table><thead><tr><th>Saat</th><th>Plaka</th><th>Kamera</th><th>Durum</th><th>OCR</th></tr></thead><tbody id="rows"></tbody></table></div><small>AI önerileri OCR sonucunu veya geçiş iznini otomatik değiştirmez.</small></div><div class="card"><h2>Kamera envanteri</h2><div id="cameras"></div><p>Kamera ekleme, kalibrasyon ve canlı görüntü masaüstü uygulamasında yönetilir.</p></div></section>
<aside><div class="card"><span class="badge">YEREL GÖRSEL AI</span><h2>İkinci gözünüz.</h2><p>Gemma, olayın görsel kanıtını bağımsız inceler. Son karar operatöründür.</p><form id="settings"><label><input id="enabled" type="checkbox"> AI desteğini etkinleştir</label><label for="model">Görsel model</label><select id="model"><option>gemma3:4b</option><option>gemma3:12b</option></select><p><small>4B daha az bellek kullanır. 12B daha fazla RAM / VRAM gerektirir. İlk hazırlıkta Ollama ve model otomatik indirilir; internet ve birkaç GB boş alan gerekir.</small></p><div class="actions"><button class="primary" id="save">Ayarları kaydet</button><button type="button" id="prepare">Motoru ve modeli hazırla</button></div></form><p id="aiStatus"></p><progress id="progress" hidden style="width:100%"></progress><p><small>Görseller yalnızca bu bilgisayardaki Ollama motoruna gönderilir. AI kapalıyken standart OCR çalışmaya devam eder.</small></p></div></aside></div></section></main>
<dialog id="details"><div class="actions"><button id="close">Kapat</button><span class="badge" id="eventLabel"></span></div><div id="images"></div><p id="eventInfo"></p><div class="actions"><button id="review" class="primary">AI ile görseli incele</button></div><div id="result">Henüz AI önerisi yok.</div><form id="correction"><label for="plate">Operatörün doğruladığı plaka</label><input id="plate" maxlength="16" required><label for="reason">Düzeltme gerekçesi</label><input id="reason" minlength="3" maxlength="500" required><div class="actions"><button class="primary">Doğruladığım düzeltmeyi kaydet</button></div></form><small>Düzeltme kullanıcı ve gerekçeyle denetim kaydına yazılır; orijinal OCR korunur.</small></dialog>
<script>
const $=id=>document.getElementById(id);let csrf='',state=null,selected=null,busy=false,lastRows='';
function notice(text){$('notice').textContent=text}
async function api(path,body){const response=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-CSRF-Token':csrf}:{},body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok){if(response.status===401){$('workspace').hidden=true;$('login').hidden=false;$('logout').hidden=true;$('details').close()}throw Error(data.error||'İşlem başarısız')}return data}
function node(tag,text){const n=document.createElement(tag);n.textContent=text;return n}
function renderRows(){const query=$('search').value.toLocaleUpperCase('tr');const rows=state.events.filter(e=>(e.plate+' '+e.camera_name+' '+(e.corrected_plate||'')).toLocaleUpperCase('tr').includes(query));const signature=JSON.stringify(rows);if(signature===lastRows)return;lastRows=signature;$('rows').replaceChildren();for(const e of rows){const tr=document.createElement('tr');tr.dataset.id=e.event_id;tr.tabIndex=0;tr.setAttribute('aria-label',(e.corrected_plate||e.plate||'Okunamadı')+' olay detayı');for(const value of [new Date(e.at*1000).toLocaleString('tr-TR'),e.corrected_plate||e.plate||'Okunamadı',e.camera_name,e.status,Math.round(e.confidence*100)+'%'])tr.append(node('td',value));tr.onclick=()=>openEvent(e.event_id);tr.onkeydown=x=>{if(x.key==='Enter')openEvent(e.event_id)};$('rows').append(tr)}}
function renderAI(){const ai=state.ai;$('aiStatus').textContent=ai.message;$('progress').hidden=!ai.total;if(ai.total){$('progress').max=ai.total;$('progress').value=ai.completed||0}const result=ai.result;if(selected&&result&&result.event_id===selected.event_id){$('result').textContent=(result.readable?'Önerilen plaka: '+result.plate:'Plaka güvenle okunamadı')+'\n'+result.reason+'\n'+(result.agrees?'OCR ile aynı okuma.':'OCR ile karşılaştırıp görselden doğrulayın.')}else if(selected){$('result').textContent=ai.event_id===selected.event_id?ai.message:'Bu olay için AI önerisi yok.'}$('review').disabled=!state.settings.enabled||state.role==='auditor';}
async function refresh(initial=false){if(busy||document.hidden)return;busy=true;try{state=await api('state');csrf=state.csrf;$('login').hidden=true;$('workspace').hidden=false;$('logout').hidden=false;$('identity').textContent=state.username+' · '+state.role+' · Aynı yerel veritabanı · 5 saniyede bir güncellenir';$('cameraCount').textContent=state.cameras.length;$('eventCount').textContent=state.events.length;$('reviewCount').textContent=state.events.filter(e=>e.status!=='recognized'&&!e.corrected_plate).length;if(initial){$('enabled').checked=state.settings.enabled;$('model').value=state.settings.model}for(const id of ['enabled','model','save','prepare'])$(id).disabled=state.role!=='admin';$('correction').hidden=state.role==='auditor';$('cameras').replaceChildren(...state.cameras.map(c=>node('p',c.name+' · '+c.direction)));renderRows();renderAI()}catch(e){if(initial)notice(e.message)}finally{busy=false}}
async function action(fn){try{await fn();notice('')}catch(e){notice(e.message);if($('details').open)$('result').textContent=e.message}}
async function openEvent(id){await action(async()=>{selected=await api('event',{id});$('eventLabel').textContent=selected.camera_name;$('eventInfo').textContent='OCR: '+(selected.plate||'Okunamadı')+' · '+new Date(selected.at*1000).toLocaleString('tr-TR')+' · '+selected.corrections.length+' düzeltme';$('images').replaceChildren();for(const [name,data]of Object.entries(selected.images)){const img=document.createElement('img');img.src='data:image/jpeg;base64,'+data;img.alt=name==='plate'?'Plaka kanıtı':'Araç kanıtı';$('images').append(img)}if(!Object.keys(selected.images).length)$('images').append(node('p','Bu olay için görsel kanıt saklanmamış.'));$('plate').value=selected.corrections.at(-1)?.plate||selected.plate;$('reason').value='';renderAI();$('details').showModal()})}
$('signIn').onsubmit=e=>{e.preventDefault();action(async()=>{const v=await api('login',{username:$('username').value,password:$('password').value});csrf=v.csrf;$('password').value='';await refresh(true)})};$('logout').onclick=()=>action(async()=>{await api('logout',{});location.reload()});$('search').oninput=renderRows;$('close').onclick=()=>$('details').close();$('settings').onsubmit=e=>{e.preventDefault();action(async()=>{await api('settings',{enabled:$('enabled').checked,model:$('model').value});await refresh(true)})};$('prepare').onclick=()=>action(async()=>{await api('prepare',{});await refresh()});$('review').onclick=()=>action(async()=>{await api('review',{id:selected.event_id});await refresh()});$('correction').onsubmit=e=>{e.preventDefault();action(async()=>{await api('correct',{id:selected.event_id,plate:$('plate').value,reason:$('reason').value});$('details').close();await refresh()})};refresh(true);setInterval(()=>{if(!$('workspace').hidden)refresh()},5000);
</script></html>'''
